-- PT115-S4-Q25. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT115-S4-Q25$batch05$ AND q.stimulus=$batch05$Political commentator: Voters tend to elect the candidate whose visual image most evokes positive feelings. Thus, laws designed to increase the fairness of elections should not allow one candidate to buy significantly more media exposure than any rival candidates can afford.$batch05$ AND q.prompt=$batch05$Which one of the following is an assumption on which the political commentator's argument depends?$batch05$ AND q.correct_choice=$batch05$C$batch05$) THEN RAISE EXCEPTION 'Question changed: PT115-S4-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT115-S4-Q25$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S4-Q25'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT115-S4-Q25$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$Fair election laws should not let one candidate buy far more media exposure than rivals can afford.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Voters tend to elect the candidate whose visual image stirs the most positive feelings.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Look at the two nouns. The evidence is about a candidate's *image*. The conclusion is about *media exposure*. The commentator never says how one leads to the other. If more airtime did nothing for how voters feel about a candidate's image, buying more of it would be harmless. This is a link question: the answer will tie exposure to image.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A link: more media exposure can make a candidate's image land better with voters.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT115-S4-Q25$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$"Unfair *only if*" makes resources the single possible source of unfairness. The commentator only needs this one kind of imbalance to be unfair, not every unfair election to trace back to money.$batch05$), ($batch05$B$batch05$, $batch05$Familiarity might be one route to positive feelings, but "only when" shuts out every other route. The argument does not need that.$batch05$), ($batch05$C$batch05$, $batch05$Notice how gentle "at least sometimes" is. That is what you want in a necessary assumption: just enough to hold the argument up. Negate it: "more media exposure *never* makes a candidate's image evoke more positive feelings." Now buying airtime gives no edge at all, and there is nothing for the fairness law to prevent.$batch05$), ($batch05$D$batch05$, $batch05$Whether candidates always spend to the limit does not matter. The worry is that some *can* buy much more, and that it would help them.$batch05$), ($batch05$E$batch05$, $batch05$"Will not be elected" turns a tendency into a guarantee. The commentator only says voters *tend* to pick the candidate with the stronger image.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT115-S4-Q25$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
